import{_ as a,o as i,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"创游世界动作状态机入门","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界动作状态机入门.md","filePath":"脚本系统/专题研究/创游世界动作状态机入门.md","lastUpdated":1777893104000}'),d={name:"脚本系统/专题研究/创游世界动作状态机入门.md"};function h(o,l,c,n,t,s){return i(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="创游世界动作状态机入门" tabindex="-1">创游世界动作状态机入门 <a class="header-anchor" href="#创游世界动作状态机入门" aria-label="Permalink to “创游世界动作状态机入门”">​</a></h1><ul><li>分类：脚本 / 战斗 / 动作逻辑</li><li>子系统：动作状态 / 战斗 / 输入控制 / 中断规则</li><li>关键词标签：状态机, 动作状态, 攻击, 跑步, 翻滚, 受击, 死亡, 输入锁</li><li>来源类型：战斗系统专题、脚本实战架构专题、视频主题交叉整理</li><li>证据等级：多来源交叉归纳</li><li>完整度状态：深度整理</li><li>来源文件：<code>docs/脚本系统/专题研究/创游世界战斗系统设计入门.md</code>; <code>docs/脚本系统/专题研究/创游世界脚本实战架构入门.md</code>; <code>docs/教程资料/B站创游世界视频资源清单.md</code></li><li>来源截图编号：<code>待继续细化；可先从战斗系统专题、脚本实战架构专题及相关教程材料反查补充</code></li><li>对应 OCR 文档：<code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>最后更新：2026-04-20</li><li>适合查询：动作为什么会打架、状态机该怎么理解、翻滚攻击受击死亡怎么组织、输入锁怎么做</li></ul><h2 id="_1-什么是状态机" tabindex="-1">1. 什么是状态机 <a class="header-anchor" href="#_1-什么是状态机" aria-label="Permalink to “1. 什么是状态机”">​</a></h2><p>状态机可以先用最简单的话理解：</p><blockquote><p><strong>一个对象在同一时刻，只应该处于少数明确状态中的某一个。</strong></p></blockquote><p>比如玩家角色：</p><ul><li>待机</li><li>移动</li><li>攻击</li><li>翻滚</li><li>受击</li><li>死亡</li></ul><p>如果没有这种清晰分层，后期就很容易出现：</p><ul><li>一边翻滚一边又进入普通攻击</li><li>死亡后还能移动</li><li>受击时还能继续连按触发多个动作</li></ul><hr><h2 id="_2-为什么动作类项目特别需要状态机" tabindex="-1">2. 为什么动作类项目特别需要状态机 <a class="header-anchor" href="#_2-为什么动作类项目特别需要状态机" aria-label="Permalink to “2. 为什么动作类项目特别需要状态机”">​</a></h2><p>动作类玩法的问题，不是“会不会播放动画”，而是：</p><ul><li>哪个动作优先级更高</li><li>哪个动作能不能打断另一个动作</li><li>哪个状态下允许输入</li><li>哪个状态下必须锁输入</li></ul><p>状态机就是用来回答这些问题的。</p><hr><h2 id="_3-常见状态有哪些" tabindex="-1">3. 常见状态有哪些 <a class="header-anchor" href="#_3-常见状态有哪些" aria-label="Permalink to “3. 常见状态有哪些”">​</a></h2><h3 id="_3-1-待机" tabindex="-1">3.1 待机 <a class="header-anchor" href="#_3-1-待机" aria-label="Permalink to “3.1 待机”">​</a></h3><p>没有明显动作输入时的默认状态。</p><h3 id="_3-2-移动" tabindex="-1">3.2 移动 <a class="header-anchor" href="#_3-2-移动" aria-label="Permalink to “3.2 移动”">​</a></h3><p>角色正在走、跑、冲刺等。</p><h3 id="_3-3-攻击" tabindex="-1">3.3 攻击 <a class="header-anchor" href="#_3-3-攻击" aria-label="Permalink to “3.3 攻击”">​</a></h3><p>普通攻击、技能攻击、蓄力攻击等。</p><h3 id="_3-4-翻滚-闪避" tabindex="-1">3.4 翻滚 / 闪避 <a class="header-anchor" href="#_3-4-翻滚-闪避" aria-label="Permalink to “3.4 翻滚 / 闪避”">​</a></h3><p>通常带有位移和短时无敌或保护逻辑。</p><h3 id="_3-5-受击" tabindex="-1">3.5 受击 <a class="header-anchor" href="#_3-5-受击" aria-label="Permalink to “3.5 受击”">​</a></h3><p>被打中后的硬直、击退或受伤反馈状态。</p><h3 id="_3-6-死亡" tabindex="-1">3.6 死亡 <a class="header-anchor" href="#_3-6-死亡" aria-label="Permalink to “3.6 死亡”">​</a></h3><p>角色不可继续执行正常行为的终止状态。</p><hr><h2 id="_4-状态机真正关键的是-切换规则" tabindex="-1">4. 状态机真正关键的是“切换规则” <a class="header-anchor" href="#_4-状态机真正关键的是-切换规则" aria-label="Permalink to “4. 状态机真正关键的是“切换规则””">​</a></h2><p>不是把状态名字写出来就叫状态机。</p><p>真正关键的是：</p><ul><li>什么条件进入某状态</li><li>什么条件退出某状态</li><li>哪些状态之间能直接切</li><li>哪些状态必须等待完成</li></ul><p>例如：</p><ul><li>待机 → 移动：有移动输入</li><li>移动 → 攻击：按下攻击键且未被锁定</li><li>攻击 → 待机：攻击结束且无后续输入</li><li>任意状态 → 死亡：生命值归零</li></ul><hr><h2 id="_5-优先级很重要" tabindex="-1">5. 优先级很重要 <a class="header-anchor" href="#_5-优先级很重要" aria-label="Permalink to “5. 优先级很重要”">​</a></h2><p>不是所有状态地位都一样。</p><p>常见优先级思路：</p><ul><li>死亡最高</li><li>受击通常高于普通移动</li><li>翻滚可能高于普通攻击，或与攻击互斥</li><li>普通移动低于很多特殊动作</li></ul><p>如果没有优先级，后面很容易动作打架。</p><hr><h2 id="_6-中断规则要提前想清楚" tabindex="-1">6. 中断规则要提前想清楚 <a class="header-anchor" href="#_6-中断规则要提前想清楚" aria-label="Permalink to “6. 中断规则要提前想清楚”">​</a></h2><p>状态机里最常见的问题就是“能不能打断”。</p><p>要明确：</p><ul><li>攻击中能不能翻滚取消</li><li>受击时能不能释放技能</li><li>翻滚过程中能不能再触发翻滚</li><li>死亡后是不是彻底锁住全部动作</li></ul><p>这些规则一旦不清楚，项目后面会非常乱。</p><hr><h2 id="_7-输入锁是什么" tabindex="-1">7. 输入锁是什么 <a class="header-anchor" href="#_7-输入锁是什么" aria-label="Permalink to “7. 输入锁是什么”">​</a></h2><p>输入锁不是不能输入，而是：</p><blockquote><p>在某些状态下，即使玩家有输入，也不允许立刻触发新行为。</p></blockquote><p>常见场景：</p><ul><li>攻击前摇 / 后摇</li><li>受击硬直</li><li>死亡状态</li><li>结算动画期间</li></ul><p>如果没有输入锁，动作类项目通常会非常漂。</p><hr><h2 id="_8-一个最小动作状态设计示例" tabindex="-1">8. 一个最小动作状态设计示例 <a class="header-anchor" href="#_8-一个最小动作状态设计示例" aria-label="Permalink to “8. 一个最小动作状态设计示例”">​</a></h2><p>假设你做一个简单角色：</p><h3 id="可用状态" tabindex="-1">可用状态 <a class="header-anchor" href="#可用状态" aria-label="Permalink to “可用状态”">​</a></h3><ul><li>待机</li><li>移动</li><li>攻击</li><li>翻滚</li><li>受击</li><li>死亡</li></ul><h3 id="最小规则" tabindex="-1">最小规则 <a class="header-anchor" href="#最小规则" aria-label="Permalink to “最小规则”">​</a></h3><ul><li>有移动输入且不在特殊状态 → 进入移动</li><li>无移动输入且不在特殊状态 → 回到待机</li><li>按攻击键且当前允许攻击 → 进入攻击</li><li>按翻滚键且当前允许翻滚 → 进入翻滚</li><li>被命中且未死亡 → 进入受击</li><li>血量归零 → 进入死亡</li></ul><p>这已经比“全写 if 判断混在一起”稳很多。</p><hr><h2 id="_9-状态机和战斗系统的关系" tabindex="-1">9. 状态机和战斗系统的关系 <a class="header-anchor" href="#_9-状态机和战斗系统的关系" aria-label="Permalink to “9. 状态机和战斗系统的关系”">​</a></h2><p>战斗系统不是只有伤害计算。</p><p>动作类战斗至少还涉及：</p><ul><li>攻击什么时候生效</li><li>受击什么时候触发</li><li>无敌时间什么时候开始/结束</li><li>攻击后什么时候能接下个动作</li></ul><p>这些都高度依赖状态机。</p><p>所以可以把它理解成：</p><ul><li>战斗系统管“战斗规则”</li><li>状态机管“动作流程秩序”</li></ul><hr><h2 id="_10-新手最常见错误" tabindex="-1">10. 新手最常见错误 <a class="header-anchor" href="#_10-新手最常见错误" aria-label="Permalink to “10. 新手最常见错误”">​</a></h2><h3 id="_10-1-所有动作都靠散乱布尔值控制" tabindex="-1">10.1 所有动作都靠散乱布尔值控制 <a class="header-anchor" href="#_10-1-所有动作都靠散乱布尔值控制" aria-label="Permalink to “10.1 所有动作都靠散乱布尔值控制”">​</a></h3><p>后期会出现：</p><ul><li><code>isRun</code></li><li><code>isAttack</code></li><li><code>isHit</code></li><li><code>isDead</code></li><li><code>isRoll</code></li></ul><p>一多起来很容易互相冲突。</p><h3 id="_10-2-没有统一状态入口" tabindex="-1">10.2 没有统一状态入口 <a class="header-anchor" href="#_10-2-没有统一状态入口" aria-label="Permalink to “10.2 没有统一状态入口”">​</a></h3><p>导致不同脚本各改各的状态名，最终谁都说不清当前到底在什么状态。</p><h3 id="_10-3-没有死亡最高优先级" tabindex="-1">10.3 没有死亡最高优先级 <a class="header-anchor" href="#_10-3-没有死亡最高优先级" aria-label="Permalink to “10.3 没有死亡最高优先级”">​</a></h3><p>这会导致死亡后还能放技能、移动、播错误动作。</p><h3 id="_10-4-没想清中断规则" tabindex="-1">10.4 没想清中断规则 <a class="header-anchor" href="#_10-4-没想清中断规则" aria-label="Permalink to “10.4 没想清中断规则”">​</a></h3><p>很多“手感奇怪”本质都是中断逻辑没设计清楚。</p><hr><h2 id="_11-一句很好记的总结" tabindex="-1">11. 一句很好记的总结 <a class="header-anchor" href="#_11-一句很好记的总结" aria-label="Permalink to “11. 一句很好记的总结”">​</a></h2><blockquote><p><strong>状态机不是为了显得高级，而是为了防止动作互相打架。</strong></p></blockquote><p>只要项目里出现：</p><ul><li>攻击</li><li>受击</li><li>翻滚</li><li>技能</li><li>死亡</li></ul><p>基本就值得认真做状态管理。</p><hr><h2 id="_11-结论等级与待验证问题" tabindex="-1">11. 结论等级与待验证问题 <a class="header-anchor" href="#_11-结论等级与待验证问题" aria-label="Permalink to “11. 结论等级与待验证问题”">​</a></h2><h3 id="已确认" tabindex="-1">已确认 <a class="header-anchor" href="#已确认" aria-label="Permalink to “已确认”">​</a></h3><ul><li><code>[已确认]</code> 动作类项目一旦同时存在攻击、翻滚、受击、死亡等行为，就必须明确状态切换与优先级，否则极易出现动作互相打架。</li><li><code>[已确认]</code> 输入锁、中断规则与优先级并不是附属细节，而是动作状态设计的核心组成部分。</li></ul><h3 id="高可信推断" tabindex="-1">高可信推断 <a class="header-anchor" href="#高可信推断" aria-label="Permalink to “高可信推断”">​</a></h3><ul><li><code>[高可信推断]</code> 对大多数动作项目来说，建立统一状态入口会比散乱布尔值控制更稳，也更容易维护。</li><li><code>[高可信推断]</code> 如果后续还会扩展技能、连招、硬直、无敌帧与取消机制，越早建立状态机边界，返工成本越低。</li></ul><h3 id="待验证" tabindex="-1">待验证 <a class="header-anchor" href="#待验证" aria-label="Permalink to “待验证”">​</a></h3><ul><li><code>[待验证]</code> 不同项目规模下，状态数量拆到多细、是否拆分为角色主状态与动作子状态，仍需要更多案例支持。</li></ul><h2 id="_12-证据与回查入口" tabindex="-1">12. 证据与回查入口 <a class="header-anchor" href="#_12-证据与回查入口" aria-label="Permalink to “12. 证据与回查入口”">​</a></h2><ul><li>主要交叉来源：<code>docs/脚本系统/专题研究/创游世界战斗系统设计入门.md</code>、<code>docs/脚本系统/专题研究/创游世界脚本实战架构入门.md</code></li><li>OCR 反查入口：<code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>编号映射入口：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>说明：本页目前已补最小回链，但更细的截图编号仍建议后续按战斗与动作专题继续补强。</li></ul><h2 id="_13-关联阅读" tabindex="-1">13. 关联阅读 <a class="header-anchor" href="#_13-关联阅读" aria-label="Permalink to “13. 关联阅读”">​</a></h2><ul><li><code>docs/脚本系统/专题研究/创游世界战斗系统设计入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界脚本实战架构入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li><code>docs/教程资料/B站创游世界视频资源清单.md</code></li></ul>',100)])])}const b=a(d,[["render",h]]);export{_ as __pageData,b as default};
